INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokemomcore', 'Travel through Pallet Town and Viridian Town after an anti-capitalist and anti-speciesist revolution! Red, Blue, Green and Yellow have fought to emancipate Kanto from the grip of the Pokémon League and its alienating power over the people. And you, you play as GAMIN Lesli who has to pick up a package for their MOM so she can make pottery this weekend with her friends! Will you arrive in time to get the package and will there be any rhubarb pie left?' FROM games WHERE igdb_id = 299120 ON CONFLICT (game_id, language_code) DO NOTHING;
