INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m in Love With Your Dead Grandmother Presents: Noah SmallJohnson''s Puzzle Game', 'In memory of a woman he never met, Noah SmallJohnson creates the most epic puzzle game ever. Featuring high-score gameplay, catchy tunes, multiple arcade modes, and a Game Show where players can win cheat codes. It’s weird, it’s wild, and it’s unapologetically heartfelt.' FROM games WHERE igdb_id = 321519 ON CONFLICT (game_id, language_code) DO NOTHING;
