INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Light Dark', 'The screen is split horizontally in two halves: light and dark, and the dark side is upside down. You are constantly moving forward and every time you press a button you switch between the sides. You also jump by pressing a button and can fly some distance by holding a button. Collect the coins to score points and avoid hitting the spikes.' FROM games WHERE igdb_id = 273573 ON CONFLICT (game_id, language_code) DO NOTHING;
