INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NoEvidence: Scary Horror Quest Survival Story', 'NoEvidence is an intense detective game where you investigate a murder. Navigate a dark environment using only your flashlight. Discover the murder location and prevent the crime. Use detective skills to find clues and important objects like a recorder, tapes, fuses, and a revolver. Solve puzzles and decipher codes to unlock doors and access key areas. With its immersive atmosphere, challenging quests, and gripping storyline, it''s a must-play for detective game and thriller fans.' FROM games WHERE igdb_id = 251485 ON CONFLICT (game_id, language_code) DO NOTHING;
