INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bus Simulator: City Driving Ultimate', 'Step into the driver''s seat of a variety of meticulously detailed buses and embark on a captivating journey through bustling city streets in "Bus Simulator - City Driving Ultimate" As a skilled bus operator, your mission is to faithfully follow designated routes, pick up passengers, and deliver them safely to their destinations. The city''s intricate traffic patterns, unpredictable road conditions, and the needs of your passengers will put your driving prowess and multitasking abilities to the test.' FROM games WHERE igdb_id = 264902 ON CONFLICT (game_id, language_code) DO NOTHING;
