INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX vs. ATV: Legends - Season One: Exclusive Box Edition', 'MX vs ATV Legends Season One marks the newest addition to the popular MX vs ATV off-road racing franchise. With this game, players can fulfill their dream of becoming a renowned off-road rider, garnering widespread recognition and admiration from fans and sponsors alike. Whether they choose to play the career or online modes, they''ll get to experience the thrill of racing to the finish line on bikes, ATVs, and UTVs. This latest instalment also boasts expansive open environments and a comprehensive career mode, allowing players to immerse themselves fully in the world of professional off-road racing and enjoy all the highs and lows that come with it.INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 252169 AND p.igdb_id = 169 ON CONFLICT DO NOTHING;
