INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Gate', 'Night Gate is the result of crossing an open-world Castlevania with the action of Resident Evil. You play as a Vampire Hunter on a quest to kill the Master Vampire, Grendel! Set in the swamps of the American South, take your Airboat to explore in a 20+ hour open-world RPG horror game.' FROM games WHERE igdb_id = 212967 ON CONFLICT (game_id, language_code) DO NOTHING;
