INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atelier-ryza-3-alchemist-of-the-end-and-the-secret-key-digital-deluxe-edition', 239259, '2023-03-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6aym.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar27b7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Ryza 3: Alchemist of the End & the Secret Key - Digital Deluxe Edition', 'The story begins when a group of islands called Kark Isles appear near Ryza''s—the protagonist''s—hometown. Seeing this as a threat to their home, Ryza and her friends investigate the isles and discover ruins with a huge gate. Just as Ryza approaches the gate, a strange voice echoes in her head, telling her to reach the Code of the Universe. What is it that lies beyond the gate, and what does the "Code of the Universe" mean? In hopes of finding a way to save their home, Ryza and her friends set off on a great adventure that revolves around a Key and the roots of alchemy.' FROM games WHERE igdb_id = 239259 ON CONFLICT (game_id, language_code) DO NOTHING;
