INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreams of Saturn', 'Dreams of Saturn is a Shenmue Xmas fan game from George Kitchen. The game features around 10-15 hours worth of content in the form of a short Shenmue story, taking place before and after the events of the original Shenmue, along with a wide variety of mini-games, achievements and more.' FROM games WHERE igdb_id = 281074 ON CONFLICT (game_id, language_code) DO NOTHING;
