INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Final Bastion', 'The Final Bastion is a Multiplayer PvP & PvE Tower-defense with a classic Medieval-Fantasy theme. Compete against players in head to head online in a PvP, sending waves against the enemy and growing your economy. Play side by side with your friends in PvE and see who survives the longest.' FROM games WHERE igdb_id = 238507 ON CONFLICT (game_id, language_code) DO NOTHING;
