INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-turkey-hunting', 234077, '2023-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65ep.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23he.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Turkey Hunting', 'Experience virtual spring gobbler hunting at it''s finest! Whether you are a turkey hunter that needs off season action or a game enthusiast that enjoys playing true to life hunting simulations ''Pro Turkey Hunting'' is the fix you need. Game play centers around the four wild turkey sub-species residing in North America; easterns, osceolas, rios and merriams. Harvesting each sub-species is referred to as the ''Grand Slam'' of turkey hunting. Get close to that gobbler and use your calls and decoy to lure him in. But be careful not to move too abruptly, these old gobblers have incredible eyesight! Challenge yourself and see if you have what it takes to earn the coveted ''Grand Slam''!' FROM games WHERE igdb_id = 234077 ON CONFLICT (game_id, language_code) DO NOTHING;
