INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Man''s Revenge', 'Tim Martin shrugs off his loss of height but cries over his lost soup. He embarks on an epic adventure in an innocent, yet sinister man''s house, using his skills in Gliding, Climbing, and Dodging to steal everything he can. With his haul, he hopes to afford his beloved soup once again.' FROM games WHERE igdb_id = 258463 ON CONFLICT (game_id, language_code) DO NOTHING;
