INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kimono-cats', 249774, '2023-03-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hss.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vad.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kimono Cats', 'Kimono Cats is a charming, easy to play game for all ages. Select your main-character cat and a companion-cat, and walk through a Japanese "matsuri" Festival, making your companion happy. Throw darts at moving bubbles to give your companion a gift from a stall, play a mini-game, or encounter characters. Earn coins, to progress along the road to new areas that have new things to discover. Coins also allow you to purchase houses, shops, and decorative objects to design and build your own unique village. You can take care of your village and visit other players'' villages, earning bonus coins, leaving gifts, messages, and stamps in their guest books. Play online or offline. Kimono Cats is designed to help you smile a bit more every day.' FROM games WHERE igdb_id = 249774 ON CONFLICT (game_id, language_code) DO NOTHING;
