INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidey Spot', 'There are presents hidden around the house. Who can wait for Christmas morning to open them all? Sneak around in the middle of the night and find the goodies before your family wakes up. And who knows—maybe it''ll turn out there''s something else for you to discover in the home you thought you knew so well…' FROM games WHERE igdb_id = 240972 ON CONFLICT (game_id, language_code) DO NOTHING;
