INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Totoge', 'Totoge is a fast-paced one-button game. You control a chicken that is constantly falling down towards one of the sides of the screen. Your goal is to avoid landing on the randomly appearing spikes. Press a button to jump in the air and you will score additional points for jumping depending on the distance passed. You will turn around when you hit the sides of the screen. The game is over when you hit the spikes.' FROM games WHERE igdb_id = 262732 ON CONFLICT (game_id, language_code) DO NOTHING;
