INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Collection of Mini-Games', 'This is just a handful of mini-games that I created as I learn how to use and just play around with my RPGMaker. I created these just for fun, but was happy enough with the results that I wanted to let them be played by people to get their opinions, or any advice they may have.' FROM games WHERE igdb_id = 263641 ON CONFLICT (game_id, language_code) DO NOTHING;
