INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eternity', 'Eternity is a 2D turn-based RPG that immerses players in a world of fantasy and adventure. Heroes and players take turns casting magical abilities to clear rooms of enemies and receive randomly generated loot. Gameplay includes questing via a quest book, climbing the infinitely tall Dark Tower, crafting items and new heroes at the forge, building the strongest team possible with character management, and teaming up with other heroes in co-op multiplayer.' FROM games WHERE igdb_id = 276757 ON CONFLICT (game_id, language_code) DO NOTHING;
