INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'K-Jo Chases the Cheese', 'The slight mouse K-Jo, accustomed to the tranquility of the countryside, found himself in trouble when trying to fight for food in the city. He needs your help to escape the mousetraps, collect cheeses, score points and leave each room before time runs out, and so go through the 120 existing levels.' FROM games WHERE igdb_id = 321655 ON CONFLICT (game_id, language_code) DO NOTHING;
