INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Down the Eye of the Tiger', 'A burnt out Las Vegas cocktail waitress has grown to resent her life, her city, and her choices. In the wake of an incident at her job, she decides to dedicate some more time to "self care" (sleeping, adopting avoidant behaviors, ditching work), and finds her dreams blending with those of the magician''s white tiger at the casino where she works.' FROM games WHERE igdb_id = 257195 ON CONFLICT (game_id, language_code) DO NOTHING;
