INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea of Thieves: Deluxe Edition', 'Celebrate five years of Sea of Thieves with this special edition, which includes a copy of the game with all permanent content added since launch, plus a wide-ranging assortment of extra cosmetics and collector’s items. In addition to the 2023 Edition bonus content – Hunter Cutlass, Hunter Pistol, Hunter Compass, Hunter Hat, Hunter Jacket, Hunter Sails and 10,000 gold – this edition of the game comes with a further Deluxe Bundle containing the Black Phoenix Figurehead, Black Phoenix Sails, Crab Dab Emote, Deck Hide Emote and 550 Ancient Coins for use in the Pirate Emporium.' FROM games WHERE igdb_id = 241859 ON CONFLICT (game_id, language_code) DO NOTHING;
