INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9Ball Pocket', '9-Ball Pocket brings you eight-ball pool, also known as American billiards. You can compete with up to 4 friends or against the AI in Versus mode, or challenge the best in the world in Arcade mode, where you can make combo shots and rack up points to become Number 1 in the online ranking. All of this comes in a setting with great graphics and Jazz music.' FROM games WHERE igdb_id = 284756 ON CONFLICT (game_id, language_code) DO NOTHING;
