INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flesh Prison', 'Flesh prison. Who is trapped? You? Or your mech. Blast your foes with immense firepower. Rocket launchers, machine guns, and your trusty massive flesh saw. Turn off your lights, close the door, turn up the volume and rip the knob off. Blow them to pieces as this is what you are now, you are no different than the beasts you massacre. Is this earth? Or is this hell?' FROM games WHERE igdb_id = 323209 ON CONFLICT (game_id, language_code) DO NOTHING;
