INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweet Dreams Alex', 'Sweet Dreams Alex is a cute, relaxing puzzle game in which you build labyrinths to keep Nightmares away. Every level presents a new challenge that you can solve in a variety of creative ways while experiencing a cute slice-of-life story about the wonders of childhood. Sweet Dreams Alex draws inspiration from the maze-building of classic tower defense games and the construction-based puzzle-solving of modern games like Poly Bridge and World of Goo.' FROM games WHERE igdb_id = 157545 ON CONFLICT (game_id, language_code) DO NOTHING;
