INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drift Reign', 'Get ready to reign supreme in the ultimate drifting simulator - Drift Reign! Start as a street drifter, choose your car from USA, Japan, or Germany, and work your way up to the top. With realistic physics and deep customization options, this game will make you feel like a real pro-drifter.' FROM games WHERE igdb_id = 245834 ON CONFLICT (game_id, language_code) DO NOTHING;
